// Anonymous usage stats, one document per day in the "stats" storage
// (see nitro.storage in nuxt.config.ts). No name, no IP: only counters and a
// random visitor id generated by the browser, used to count unique visitors.

export interface QuizCounter {
  starts: number
  ends: number
  answered: number // questions answered in finished quizzes
  correct: number
}

export interface QuestionCounter {
  label: string
  quiz: string
  n: number
  ok: number
  mid: number
}

export interface DayStats {
  visitors: Record<string, 1>
  views: Record<string, number>
  modules: Record<string, number> // "niveau2 · Titre du module"
  fiches: Record<string, number>
  quizzes: Record<string, QuizCounter> // "n2 · qcm · Physique + Réglementation"
  questions: Record<string, QuestionCounter>
}

export const emptyDay = (): DayStats => ({
  visitors: {},
  views: {},
  modules: {},
  fiches: {},
  quizzes: {},
  questions: {},
})

// Caps so that a script hammering the endpoint can't grow a day document forever
export const MAX_KEYS = 400

const storage = () => useStorage('stats')

export const dayKey = (d = new Date()) => d.toISOString().slice(0, 10)

export const readDay = async (key: string): Promise<DayStats> => ({
  ...emptyDay(),
  ...((await storage().getItem<DayStats>(key)) ?? {}),
})

// Writes are read-modify-write: chain them so two requests can't overwrite
// each other (enough for a single server instance)
let queue: Promise<unknown> = Promise.resolve()

export const updateToday = (fn: (day: DayStats) => void) => {
  const run = queue.then(async () => {
    const key = dayKey()
    const day = await readDay(key)
    fn(day)
    await storage().setItem(key, day)
  })
  queue = run.catch(() => {})
  return run
}

export const listDays = async () =>
  (await storage().getKeys())
    .map((k) =>
      k
        .split(':')
        .pop()!
        .replace(/\.json$/, '')
    )
    .filter((k) => /^\d{4}-\d{2}-\d{2}$/.test(k))
    .sort()

export const bump = (map: Record<string, number>, key: string, by = 1) => {
  if (!(key in map) && Object.keys(map).length >= MAX_KEYS) return
  map[key] = (map[key] ?? 0) + by
}
